package={"name":"doch20","version":"1.0.0","private":True,"type":"module","scripts":{"start":"node server.js","dev":"node --watch server.js"},"dependencies":{"express":"^5.1.0","dotenv":"^16.6.1"}}
(root/'package.json').write_text(json.dumps(package,indent=2),encoding='utf-8')
(root/'.env.example').write_text('''PORT=3000\nAPP_BASE_URL=http://localhost:3000\nAPP_SECRET=replace-with-a-long-random-secret\nSTRAVA_CLIENT_ID=\nSTRAVA_CLIENT_SECRET=\nSTRAVA_REDIRECT_URI=http://localhost:3000/api/strava/callback\n''',encoding='utf-8')

server = r'''import express from "express";
import dotenv from "dotenv";
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

dotenv.config();
const __dirname=path.dirname(fileURLToPath(import.meta.url));
const app=express();
const PORT=Number(process.env.PORT||3000);
const BASE=process.env.APP_BASE_URL||`http://localhost:${PORT}`;
const STORE=path.join(__dirname,"data/store.json");
const PLAN=JSON.parse(fs.readFileSync(path.join(__dirname,"data/plan.json"),"utf8"));
app.use(express.json());
app.use(express.static(path.join(__dirname,"public")));
function load(){return JSON.parse(fs.readFileSync(STORE,"utf8"));}
function save(x){fs.writeFileSync(STORE,JSON.stringify(x,null,2));}
function key(){return crypto.createHash("sha256").update(process.env.APP_SECRET||"doch20-dev-only").digest();}
function enc(obj){const iv=crypto.randomBytes(12),c=crypto.createCipheriv("aes-256-gcm",key(),iv);const b=Buffer.concat([c.update(JSON.stringify(obj),"utf8"),c.final()]);return Buffer.concat([iv,c.getAuthTag(),b]).toString("base64");}
function dec(s){const b=Buffer.from(s,"base64"),iv=b.subarray(0,12),tag=b.subarray(12,28),body=b.subarray(28);const d=crypto.createDecipheriv("aes-256-gcm",key(),iv);d.setAuthTag(tag);return JSON.parse(Buffer.concat([d.update(body),d.final()]).toString("utf8"));}
app.get("/api/plan",(_,res)=>res.json(PLAN));
app.get("/api/state",(_,res)=>{const s=load();res.json({progress:s.progress,manual:s.manual,stravaConnected:!!s.strava});});
app.put("/api/progress/:id",(req,res)=>{const s=load();s.progress[decodeURIComponent(req.params.id)]={...(s.progress[decodeURIComponent(req.params.id)]||{}),...req.body};save(s);res.json({ok:true});});
app.post("/api/manual",(req,res)=>{const s=load();s.manual.push({id:crypto.randomUUID(),...req.body});save(s);res.json({ok:true});});
app.get("/api/calendar.ics",(_,res)=>{const esc=x=>String(x||"").replace(/\\/g,"\\\\").replace(/;/g,"\\;").replace(/,/g,"\\,").replace(/\n/g,"\\n");let out=["BEGIN:VCALENDAR","VERSION:2.0","PRODID:-//DOCH20//Brevet//ES","CALSCALE:GREGORIAN","X-WR-CALNAME:DOCH20 - Brevet 1000 km","X-WR-TIMEZONE:America/Santiago"];
PLAN.forEach((x,i)=>{out.push("BEGIN:VEVENT",`UID:doch20-${i}@local`,`DTSTART;TZID=America/Santiago:${x.date.replaceAll("-","")}T${x.start.replace(":","")}00`,`DTEND;TZID=America/Santiago:${x.date.replaceAll("-","")}T${x.end.replace(":","")}00`,`SUMMARY:${esc(x.title)}`,`DESCRIPTION:${esc([x.desc,x.route,x.zone,x.km?x.km+" km":""].filter(Boolean).join(" | "))}`,"END:VEVENT")});out.push("END:VCALENDAR");res.type("text/calendar").attachment("DOCH20_Brevet_1000km.ics").send(out.join("\r\n"));});
app.get("/api/strava/connect",(req,res)=>{if(!process.env.STRAVA_CLIENT_ID)return res.status(503).send("Configura STRAVA_CLIENT_ID y STRAVA_CLIENT_SECRET en .env");const p=new URLSearchParams({client_id:process.env.STRAVA_CLIENT_ID,response_type:"code",redirect_uri:process.env.STRAVA_REDIRECT_URI||`${BASE}/api/strava/callback`,approval_prompt:"auto",scope:"read,activity:read_all"});res.redirect(`https://www.strava.com/oauth/authorize?${p}`);});
app.get("/api/strava/callback",async(req,res)=>{try{if(!req.query.code)throw new Error("Strava no devolvió código");const r=await fetch("https://www.strava.com/oauth/token",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({client_id:process.env.STRAVA_CLIENT_ID,client_secret:process.env.STRAVA_CLIENT_SECRET,code:req.query.code,grant_type:"authorization_code"})});if(!r.ok)throw new Error(await r.text());const tok=await r.json();const s=load();s.strava=enc(tok);save(s);res.redirect("/?strava=connected");}catch(e){res.status(500).send(String(e));}});
async function token(){const s=load();if(!s.strava)throw new Error("Strava no conectado");let t=dec(s.strava);if((t.expires_at||0)*1000<Date.now()+60000){const r=await fetch("https://www.strava.com/oauth/token",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({client_id:process.env.STRAVA_CLIENT_ID,client_secret:process.env.STRAVA_CLIENT_SECRET,grant_type:"refresh_token",refresh_token:t.refresh_token})});if(!r.ok)throw new Error(await r.text());t=await r.json();s.strava=enc(t);save(s);}return t.access_token;}
app.post("/api/strava/sync",async(req,res)=>{try{const access=await token();const after=Math.floor(new Date("2026-07-28T00:00:00-04:00").getTime()/1000);const r=await fetch(`https://www.strava.com/api/v3/athlete/activities?after=${after}&per_page=200`,{headers:{Authorization:`Bearer ${access}`}});if(!r.ok)throw new Error(await r.text());const acts=await r.json();const rides=acts.filter(a=>["Ride","VirtualRide","MountainBikeRide","GravelRide","EBikeRide"].includes(a.sport_type||a.type));const s=load();for(const a of rides){const d=a.start_date_local.slice(0,10);const candidates=PLAN.map((p,i)=>({p,i})).filter(x=>x.p.type==="bike"&&Math.abs((new Date(x.p.date)-new Date(d))/86400000)<=1);if(!candidates.length)continue;candidates.sort((a1,a2)=>Math.abs(a1.p.km-a.distance/1000)-Math.abs(a2.p.km-a.distance/1000));const p=candidates[0].p;const id=`${p.date}|${p.start}|${p.title}`;s.progress[id]={...(s.progress[id]||{}),done:true,km:Number((a.distance/1000).toFixed(2)),seconds:a.moving_time,elevation:a.total_elevation_gain,stravaId:a.id,stravaName:a.name};}save(s);res.json({ok:true,imported:rides.length});}catch(e){res.status(500).json({ok:false,error:String(e)});}});
app.post("/api/strava/disconnect",(req,res)=>{const s=load();s.strava=null;save(s);res.json({ok:true});});
app.get("*",(_,res)=>res.sendFile(path.join(__dirname,"public/index.html")));
app.listen(PORT,()=>console.log(`DOCH20 en ${BASE}`));
'''
(root/'server.js').write_text(server,encoding='utf-8')

index = r'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#171817"><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/icon.svg"><title>DOCH20</title><style>
:root{--bg:#171817;--panel:#202120;--paper:#f2f0e8;--muted:#aaa99f;--copper:#bd6a35;--green:#7f9f81;--line:#353633}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--paper);font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif}header{padding:22px 18px 14px;position:sticky;top:0;background:rgba(23,24,23,.96);backdrop-filter:blur(12px);z-index:5}.brand{font-weight:900;letter-spacing:.18em;font-size:26px}.sub{color:var(--muted);font-size:12px;margin-top:3px}.tabs{display:flex;gap:6px;overflow:auto;padding:10px 0 0}.tabs button{background:transparent;color:var(--muted);border:0;border-bottom:2px solid transparent;padding:9px 10px;font-weight:700}.tabs button.on{color:var(--paper);border-color:var(--copper)}main{padding:12px 14px 90px;max-width:760px;margin:auto}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:15px}.metric{font-size:27px;font-weight:900}.muted{color:var(--muted);font-size:12px}.progress{height:8px;background:#30312f;border-radius:99px;overflow:hidden;margin-top:9px}.progress>div{height:100%;background:var(--copper)}.session{padding:14px 0;border-bottom:1px solid var(--line)}.session:last-child{border:0}.row{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.badge{border:1px solid var(--line);padding:3px 7px;border-radius:99px;font-size:11px}.done{opacity:.55}.done h3{text-decoration:line-through}h2{font-size:17px;margin:0 0 10px}h3{font-size:15px;margin:0 0 4px}button,.btn,input,select,textarea{font:inherit}.primary{background:var(--paper);color:#171817;border:0;border-radius:12px;padding:11px 14px;font-weight:800}.secondary{background:transparent;color:var(--paper);border:1px solid var(--line);border-radius:12px;padding:10px 12px;font-weight:700}.strava{background:#fc4c02;color:white;border:0;border-radius:12px;padding:13px 15px;font-weight:900}.fields{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}input,select,textarea{width:100%;background:#171817;color:var(--paper);border:1px solid var(--line);border-radius:11px;padding:10px}.today{border-left:3px solid var(--copper);padding-left:12px}.alert{border:1px solid #6e4a2f;background:#2b221c;color:#e1b696;border-radius:14px;padding:12px;margin-top:12px}.navbottom{position:fixed;bottom:0;left:0;right:0;background:#171817;border-top:1px solid var(--line);display:flex;justify-content:space-around;padding:7px max(8px,env(safe-area-inset-bottom))}.navbottom button{border:0;background:none;color:var(--muted);padding:9px;font-size:12px}.navbottom button.on{color:var(--paper)}a{color:inherit}.install{display:none}@media(display-mode:browser){.install{display:inline-block}}</style></head><body><header><div class="brand">DOCH20</div><div class="sub">BREVET COMPANION</div><div class="tabs"><button class="on" data-v="home">INICIO</button><button data-v="plan">PLAN</button><button data-v="stats">DATOS</button><button data-v="strava">STRAVA</button></div></header><main id="app"></main><div class="navbottom"><button class="on" data-v="home">Inicio</button><button data-v="plan">Plan</button><button data-v="stats">Datos</button><button data-v="strava">Strava</button></div><script>
let PLAN=[],STATE={progress:{},manual:[],stravaConnected:false};const app=document.getElementById('app');const id=x=>`${x.date}|${x.start}|${x.title}`;async function load(){[PLAN,STATE]=await Promise.all([fetch('/api/plan').then(r=>r.json()),fetch('/api/state').then(r=>r.json())]);render()}function realKm(){return Object.values(STATE.progress).reduce((a,x)=>a+(+x.km||0),0)+STATE.manual.reduce((a,x)=>a+(+x.km||0),0)}function complete(){return Object.values(STATE.progress).filter(x=>x.done).length}function days(){return Math.max(0,Math.ceil((new Date('2026-10-09')-new Date())/86400000))}function upcoming(){const t=new Date().toISOString().slice(0,10);return PLAN.filter(x=>x.date>=t).slice(0,6)}
function home(){const p=Math.round(complete()/PLAN.length*100);app.innerHTML=`<div class="grid"><div class="card"><div class="muted">DÍAS AL BREVET</div><div class="metric">${days()}</div></div><div class="card"><div class="muted">KM REALIZADOS</div><div class="metric">${realKm().toFixed(0)}</div></div><div class="card"><div class="muted">SESIONES</div><div class="metric">${complete()}/${PLAN.length}</div></div><div class="card"><div class="muted">CUMPLIMIENTO</div><div class="metric">${p}%</div><div class="progress"><div style="width:${p}%"></div></div></div></div><div class="card" style="margin-top:10px"><h2>PRÓXIMO</h2>${upcoming().map(card).join('')}</div><div class="alert"><b>Rodilla</b><br>Registra dolor durante, después y al día siguiente. Dolor progresivo o cambio de pedaleo = detener la progresión.</div><p><a class="btn secondary" href="/api/calendar.ics">Descargar Google Calendar</a> <button class="secondary install" onclick="installApp()">Instalar app</button></p>`}
function card(x){const s=STATE.progress[id(x)]||{};return `<div class="session ${s.done?'done':''}"><div class="row"><div><h3>${x.title}</h3><div class="muted">${x.date} · ${x.start}–${x.end} · ${x.km?x.km+' km':''} ${x.zone||''}</div></div><span class="badge">${x.type}</span></div>${x.route?`<div class="muted" style="margin-top:6px">${x.route}</div>`:''}</div>`}
function plan(){app.innerHTML=`<div class="card"><div class="fields"><input id="q" placeholder="Buscar ruta o sesión"><select id="f"><option value="">Todo</option><option value="bike">Bici</option><option value="gym">Gym</option><option value="kine">Kine</option><option value="rest">Descanso</option></select></div><div id="list"></div></div>`;const draw=()=>{let q=document.getElementById('q').value.toLowerCase(),f=document.getElementById('f').value;document.getElementById('list').innerHTML=PLAN.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!f||x.type===f)).map(x=>{const s=STATE.progress[id(x)]||{};return `<div class="session ${s.done?'done':''}"><div class="row"><div><h3>${x.title}</h3><div class="muted">${x.date} · ${x.start}–${x.end} · ${x.km?x.km+' km':''} ${x.zone||''}</div></div><input type="checkbox" ${s.done?'checked':''} onchange='setDone(${JSON.stringify(id(x))},this.checked)'></div><div class="muted">${x.route||x.desc}</div><div class="fields"><input type="number" step="0.1" placeholder="Km reales" value="${s.km??''}" onchange='setVal(${JSON.stringify(id(x))},"km",this.value)'><input type="number" min="0" max="10" placeholder="Dolor 0–10" value="${s.pain??''}" onchange='setVal(${JSON.stringify(id(x))},"pain",this.value)'></div></div>`}).join('')};q.oninput=draw;f.onchange=draw;draw()}
async function setDone(k,v){await fetch('/api/progress/'+encodeURIComponent(k),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({done:v})});await load()}async function setVal(k,f,v){await fetch('/api/progress/'+encodeURIComponent(k),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({[f]:Number(v)||0})});STATE.progress[k]=STATE.progress[k]||{};STATE.progress[k][f]=Number(v)||0}
function stats(){let vals=Object.values(STATE.progress),pain=vals.filter(x=>Number.isFinite(x.pain)).map(x=>+x.pain),avg=pain.length?(pain.reduce((a,b)=>a+b,0)/pain.length).toFixed(1):'—';app.innerHTML=`<div class="grid"><div class="card"><div class="muted">KM REAL</div><div class="metric">${realKm().toFixed(1)}</div></div><div class="card"><div class="muted">DOLOR PROMEDIO</div><div class="metric">${avg}</div></div></div><div class="card" style="margin-top:10px"><h2>REGISTRO MANUAL</h2><div class="fields"><input id="md" type="date"><input id="mn" placeholder="Actividad"><input id="mk" type="number" step="0.1" placeholder="Km"><input id="mp" type="number" min="0" max="10" placeholder="Dolor 0–10"></div><button class="primary" style="margin-top:10px" onclick="manual()">Guardar</button></div>`}
async function manual(){await fetch('/api/manual',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({date:md.value,name:mn.value,km:Number(mk.value)||0,pain:Number(mp.value)||0})});await load()}
function strava(){app.innerHTML=`<div class="card"><h2>STRAVA</h2><p class="muted">${STATE.stravaConnected?'Cuenta conectada. Puedes sincronizar tus salidas.':'Conecta tu cuenta mediante OAuth seguro.'}</p>${STATE.stravaConnected?`<button class="strava" onclick="sync()">Sincronizar actividades</button> <button class="secondary" onclick="disconnect()">Desconectar</button>`:`<a class="strava" style="display:inline-block;text-decoration:none" href="/api/strava/connect">Connect with Strava</a>`}<div class="alert">Para activarlo, el servidor necesita tu Client ID, Client Secret y dominio de callback configurados en Strava.</div></div>`}async function sync(){const r=await fetch('/api/strava/sync',{method:'POST'}),j=await r.json();alert(j.ok?`Sincronizadas ${j.imported} actividades`:j.error);await load()}async function disconnect(){await fetch('/api/strava/disconnect',{method:'POST'});await load()}
function render(){let v=document.querySelector('[data-v].on')?.dataset.v||'home';({home,plan,stats,strava}[v]||home)()}document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-v]').forEach(x=>x.classList.remove('on'));document.querySelectorAll(`[data-v="${b.dataset.v}"]`).forEach(x=>x.classList.add('on'));render()});let prompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();prompt=e});async function installApp(){if(prompt){prompt.prompt();await prompt.userChoice;prompt=null}else alert('En iPhone: Safari → Compartir → Agregar a pantalla de inicio.')}if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');load();</script></body></html>'''
(root/'public'/'index.html').write_text(index,encoding='utf-8')
(root/'public'/'manifest.webmanifest').write_text(json.dumps({"name":"DOCH20","short_name":"DOCH20","start_url":"/","display":"standalone","background_color":"#171817","theme_color":"#171817","description":"Brevet companion para entrenamiento de ultradistancia","icons":[{"src":"/icon.svg","sizes":"any","type":"image/svg+xml","purpose":"any maskable"}]},ensure_ascii=False),encoding='utf-8')
(root/'public'/'icon.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#171817"/><circle cx="256" cy="256" r="148" fill="none" stroke="#f2f0e8" stroke-width="26"/><circle cx="256" cy="256" r="22" fill="#bd6a35"/><path d="M256 108v126l100 78" fill="none" stroke="#f2f0e8" stroke-width="22" stroke-linecap="round"/><text x="256" y="460" text-anchor="middle" fill="#f2f0e8" font-family="Arial" font-size="54" font-weight="700" letter-spacing="8">DOCH20</text></svg>''',encoding='utf-8')
(root/'public'/'sw.js').write_text('''const C="doch20-v1";const A=["/","/manifest.webmanifest","/icon.svg"];self.addEventListener("install",e=>e.waitUntil(caches.open(C).then(c=>c.addAll(A))));self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;e.respondWith(fetch(e.request).then(r=>{let x=r.clone();caches.open(C).then(c=>c.put(e.request,x));return r}).catch(()=>caches.match(e.request)))})''',encoding='utf-8')
(root/'README.md').write_text('''# DOCH20\n\nPWA móvil minimalista para seguimiento de brevet.\n\n## Ejecutar\n1. Copia `.env.example` como `.env`.\n2. Ejecuta `npm install`.\n3. Ejecuta `npm start`.\n4. Abre `http://localhost:3000`.\n\n## Instalar en celular\nPublica el proyecto en un dominio HTTPS. Android: Chrome → Instalar. iPhone: Safari → Compartir → Agregar a pantalla de inicio.\n\n## Strava\nCrea una aplicación en Strava y configura en `.env`:\n- STRAVA_CLIENT_ID\n- STRAVA_CLIENT_SECRET\n- STRAVA_REDIRECT_URI=https://tu-dominio/api/strava/callback\n- APP_BASE_URL=https://tu-dominio\n- APP_SECRET=secreto largo y aleatorio\n\nLos tokens se cifran localmente con AES-256-GCM. Para múltiples usuarios se recomienda migrar `data/store.json` a PostgreSQL y añadir autenticación de usuario.\n\n## Funciones\n- PWA instalable y offline\n- plan completo precargado\n- km y sesiones realizadas\n- dolor de rodilla\n- Google Calendar `.ics`\n- OAuth Strava, refresh token y sincronización\n- asociación automática de actividades por fecha y distancia\n''',encoding='utf-8')
